import{escapeHtml}from"./utils.js";import{applyStaggerReveal}from"./motion-feedback.js";function buildSoftChallenge(e,n){const i=document.getElementById("friends-challenge");if(!i)return;if(!n.length)return i.classList.add("hidden"),void(i.innerHTML="");const a=Number(e.balance||0),s=n.map(e=>({...e,balance:Number(e.balance||0)})).sort((e,n)=>Math.abs(e.balance-a)-Math.abs(n.balance-a))[0],d=s.balance-a,l=d>0?`Сделай 2 задания и сократи разрыв на ${Math.min(d,20)} мон.`:"Удержи темп: сделай 1 задание сегодня и останься впереди.",t=d>0?`До ${escapeHtml(s.nickname)} осталось ${d} мон.`:`Ты впереди ${escapeHtml(s.nickname)} на ${Math.abs(d)} мон.`;i.innerHTML=`\n        <div class="friends-challenge__title">Дружеский челлендж недели</div>\n        <div class="friends-challenge__status">${t}</div>\n        <div class="friends-challenge__hint">${l}</div>\n    `,i.classList.remove("hidden")}export function renderFriendsUI(e){const n=document.getElementById("friends-list"),i=document.getElementById("friends-empty");if(!n)return;let a=e.friends||[];if(e.isAdmin&&e.currentChildId&&(a=a.filter(n=>!n.ownerChildId||n.ownerChildId==e.currentChildId)),0===a.length)return n.innerHTML="",i&&!e.isLoading&&i.classList.remove("hidden"),void buildSoftChallenge(e,[]);i&&i.classList.add("hidden"),buildSoftChallenge(e,a),n.innerHTML=a.map(e=>`\n        <div class="friend-item">\n            <div class="friend-info">\n                <span class="friend-nickname">${escapeHtml(e.nickname)}</span>\n                <span class="friend-balance">${e.balance} <span class="gamified-icon icon-coin-stack" aria-hidden="true"></span></span>\n            </div>\n            <div class="friend-actions"></div>\n        </div>\n    `).join(""),applyStaggerReveal(n)}